(1589785,55,16,7,29,'Mændene fra Hirjat-Jearim, Kefra og Be''erot 743;'),
(1589786,55,16,7,30,'Mændene fra Rama og Geba 621,'),
(1589787,55,16,7,31,'Mændene fra Mikmas 122,'),
(1589788,55,16,7,32,'Mændene fra Betel og Aj 123,'),
(1589789,55,16,7,33,'Mændene fra det andet Nebo 52,'),
